equation_logic_text:
var calc_output=[]; 

var source = parseFloat(source);
var innoculum = parseFloat(innoculum);
var transmission = parseFloat(transmission);
var volume = parseFloat(volume);

var basic_risk = 1/(source*innoculum*transmission);
var total_risk = basic_risk*volume;

var risk;
if (total_risk < 0.001) {
    risk = '<0.001';
}

var den = Math.round(1/total_risk * 100);
var round;

if (den <= 1000) {
    msg = 'Or, 1 in ' + den.toLocaleString() + '. PEP treatment definitely indicated, according to the article.';
    mini_msg = 'PEP treatment definitely indicated.'
    round = 1;
}

if (den > 1000 && den <= 10000) {
    msg = 'Or, 1 in ' + den.toLocaleString() + '. PEP treatment recommended, but optional, according to the article.';
    mini_msg = 'PEP treatment recommended.'
    round = 2;
}

if (den > 10000 && den <= 100000) {
    msg = 'Or, 1 in ' + den.toLocaleString() + '. PEP treatment optional but not recommended, according to the article.';
    mini_msg = 'PEP treatment optional.'
    round = 3;
}

if (den > 100000) {
    msg = 'Or, less than 1 in 100,000. PEP treatment not indicated, according to the article.';
    mini_msg = 'PEP treatment not indicated.'
    round = 4;
} 

if (total_risk == 100) {
    risk = '>99.9';
    msg = 'PEP treatment definitely indicated, according to the article.';
    mini_msg = 'PEP treatment definitely indicated.'

}

if (risk == '<0.001' || risk == '>99.9'){ 
    calc_output.push({
        name: 'mini',
        value: risk,
        value_text: '%',
        message: mini_msg
    }); 
    calc_output.push({
        name: '780_HIV Needle Stick RASP_result',
        value: risk,
        value_text: '%',
        message: msg
    }); 
} else { 
    calc_output.push({
        name: 'mini',
        value: total_risk.toFixed(round),
        value_text: '%',
        message: mini_msg
    }); 
    calc_output.push({
        name: '780_HIV Needle Stick RASP_result',
        value: total_risk.toFixed(round),
        value_text: '%',
        message: msg
    });  
}
